using System;
using System.Collections.Generic;

namespace Framework.Parameters
{
    /// <summary>
    /// 複数の実行時パラメーターを識別子によって一括管理する。
    /// </summary>
    /// <typeparam name="TParameter">
    /// パラメーターを識別する型。
    /// </typeparam>
    /// <remarks>
    /// パラメーターの状態は個体ごとに保持する。
    /// 識別子には不変の値型やenumの使用を推奨する。
    /// メインスレッドからの利用を想定する。
    /// </remarks>
    public sealed class ParameterSet<TParameter> : IDisposable
    {
        /// <summary>
        /// 識別子と実行時パラメーターの対応表。
        /// </summary>
        private readonly Dictionary<
            TParameter,
            RuntimeParameter<TParameter>> parameters =
            new Dictionary<
                TParameter,
                RuntimeParameter<TParameter>>();

        /// <summary>
        /// パラメーターごとの変更通知ハンドラー。
        /// </summary>
        private readonly Dictionary<
            TParameter,
            Action<float, float>> handlers =
            new Dictionary<
                TParameter,
                Action<float, float>>();

        /// <summary>
        /// 変更通知中かどうか。
        /// </summary>
        private bool isNotifying;

        /// <summary>
        /// 一括操作中かどうか。
        /// </summary>
        private bool isBulkOperating;

        /// <summary>
        /// 破棄済みかどうか。
        /// </summary>
        private bool isDisposed;

        /// <summary>
        /// 登録されているパラメーターの件数を取得する。
        /// </summary>
        public int Count => parameters.Count;

        /// <summary>
        /// パラメーターが登録されているかどうかを取得する。
        /// </summary>
        public bool HasParameters => parameters.Count > 0;

        /// <summary>
        /// 破棄済みかどうかを取得する。
        /// </summary>
        public bool IsDisposed => isDisposed;

        /// <summary>
        /// 登録されているパラメーターの識別子一覧を取得する。
        /// </summary>
        /// <remarks>
        /// 登録内容を反映する列挙可能な一覧を返す。
        /// 列挙中の登録および削除は行わないこと。
        /// </remarks>
        public IEnumerable<TParameter> Ids => parameters.Keys;

        /// <summary>
        /// パラメーターの最終値が変化した際に発生する。
        /// 引数は識別子、変更前の値、変更後の値の順となる。
        /// </summary>
        /// <remarks>
        /// パラメーターの状態更新後に通知する。
        /// 通知中のParameterSetに対する変更操作は禁止する。
        /// </remarks>
        public event Action<TParameter, float, float> ValueChanged;

        /// <summary>
        /// 空のパラメーター集合を生成する。
        /// </summary>
        public ParameterSet()
        {
        }

        /// <summary>
        /// 複数の定義を使用してパラメーター集合を生成する。
        /// </summary>
        /// <param name="definitions">登録する定義の一覧</param>
        /// <exception cref="ArgumentNullException">
        /// 定義一覧または個別の定義がnullの場合に発生する。
        /// </exception>
        /// <exception cref="ArgumentException">
        /// 同一識別子の定義が含まれる場合に発生する。
        /// </exception>
        public ParameterSet(
            IEnumerable<ParameterDefinition<TParameter>> definitions)
        {
            if (definitions == null)
            {
                throw new ArgumentNullException(
                    nameof(definitions));
            }

            try
            {
                foreach (var definition in definitions)
                {
                    if (!TryRegister(definition))
                    {
                        throw new ArgumentException(
                            "同一識別子の定義が含まれています。",
                            nameof(definitions));
                    }
                }
            }
            catch
            {
                // 初期化に失敗した場合は登録済み情報を解放する。
                Dispose();

                throw;
            }
        }

        /// <summary>
        /// 標準初期値を使用してパラメーターを登録する。
        /// </summary>
        /// <param name="definition">登録する定義</param>
        /// <returns>
        /// 登録に成功した場合はtrue。
        /// 同一識別子が登録済みの場合はfalse。
        /// </returns>
        /// <exception cref="ArgumentNullException">
        /// 定義がnullの場合に発生する。
        /// </exception>
        public bool TryRegister(
            ParameterDefinition<TParameter> definition)
        {
            EnsureCanModify();

            if (definition == null)
            {
                throw new ArgumentNullException(
                    nameof(definition));
            }

            return TryRegister(
                definition,
                definition.DefaultValue);
        }

        /// <summary>
        /// 個体固有の初期値を指定して登録する。
        /// </summary>
        /// <param name="definition">登録する定義</param>
        /// <param name="initialValue">個体固有の初期値</param>
        /// <returns>登録に成功した場合はtrue</returns>
        /// <exception cref="ArgumentNullException">
        /// 定義がnullの場合に発生する。
        /// </exception>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 初期値が有効範囲外の場合に発生する。
        /// </exception>
        public bool TryRegister(
            ParameterDefinition<TParameter> definition,
            float initialValue)
        {
            EnsureCanModify();

            if (definition == null)
            {
                throw new ArgumentNullException(
                    nameof(definition));
            }

            if (!definition.IsInRange(initialValue))
            {
                throw new ArgumentOutOfRangeException(
                    nameof(initialValue));
            }

            TParameter id = definition.Id;

            if (parameters.ContainsKey(id))
            {
                return false;
            }

            // 個体専用の実行時パラメーターを生成する。
            var parameter =
                new RuntimeParameter<TParameter>(
                    definition,
                    initialValue);

            // 識別子を含む変更通知へ変換する。
            Action<float, float> handler =
                (previous, current) =>
                {
                    NotifyValueChanged(
                        id,
                        previous,
                        current);
                };

            parameters.Add(id, parameter);
            handlers.Add(id, handler);

            parameter.ValueChanged += handler;

            return true;
        }

        /// <summary>
        /// 指定された識別子が登録されているか判定する。
        /// </summary>
        /// <param name="id">検索対象の識別子</param>
        /// <returns>登録されている場合はtrue</returns>
        public bool Contains(TParameter id)
        {
            ThrowIfDisposed();

            return parameters.ContainsKey(id);
        }

        /// <summary>
        /// 指定されたパラメーターを取得する。
        /// </summary>
        /// <param name="id">検索対象の識別子</param>
        /// <param name="parameter">
        /// 取得したパラメーター。失敗時はnull。
        /// </param>
        /// <returns>取得に成功した場合はtrue</returns>
        public bool TryGetParameter(
            TParameter id,
            out RuntimeParameter<TParameter> parameter)
        {
            ThrowIfDisposed();

            return parameters.TryGetValue(
                id,
                out parameter);
        }

        /// <summary>
        /// 指定されたパラメーターを取得する。
        /// </summary>
        /// <param name="id">取得対象の識別子</param>
        /// <returns>登録されている実行時パラメーター</returns>
        /// <exception cref="KeyNotFoundException">
        /// 指定された識別子が登録されていない場合に発生する。
        /// </exception>
        public RuntimeParameter<TParameter> GetParameter(
            TParameter id)
        {
            ThrowIfDisposed();

            return parameters[id];
        }

        /// <summary>
        /// 指定されたパラメーターの最終値を取得する。
        /// </summary>
        /// <param name="id">取得対象の識別子</param>
        /// <returns>補正適用後の最終値</returns>
        public float GetValue(TParameter id)
        {
            return GetParameter(id).Value;
        }

        /// <summary>
        /// 指定されたパラメーターの最終値を取得する。
        /// </summary>
        /// <param name="id">取得対象の識別子</param>
        /// <param name="value">取得した値。失敗時は0</param>
        /// <returns>取得に成功した場合はtrue</returns>
        public bool TryGetValue(
            TParameter id,
            out float value)
        {
            if (TryGetParameter(id, out var parameter))
            {
                value = parameter.Value;

                return true;
            }

            value = 0f;

            return false;
        }

        /// <summary>
        /// 指定されたパラメーターの基本値を取得する。
        /// </summary>
        /// <param name="id">取得対象の識別子</param>
        /// <returns>補正前の基本値</returns>
        public float GetBaseValue(TParameter id)
        {
            return GetParameter(id).BaseValue;
        }

        /// <summary>
        /// 指定されたパラメーターの正規化値を取得する。
        /// </summary>
        /// <param name="id">取得対象の識別子</param>
        /// <returns>0から1の正規化値</returns>
        public float GetNormalizedValue(TParameter id)
        {
            return GetParameter(id).NormalizedValue;
        }

        /// <summary>
        /// 指定されたパラメーターの基本値を変更する。
        /// </summary>
        /// <param name="id">変更対象の識別子</param>
        /// <param name="value">新しい基本値</param>
        /// <returns>基本値が変化した場合はtrue</returns>
        public bool SetBaseValue(
            TParameter id,
            float value)
        {
            EnsureCanModify();

            return GetParameter(id).SetBaseValue(value);
        }

        /// <summary>
        /// 指定されたパラメーターの基本値に加算する。
        /// </summary>
        /// <param name="id">変更対象の識別子</param>
        /// <param name="amount">加算量</param>
        /// <returns>基本値が変化した場合はtrue</returns>
        public bool AddBaseValue(
            TParameter id,
            float amount)
        {
            EnsureCanModify();

            return GetParameter(id).AddBaseValue(amount);
        }

        /// <summary>
        /// 指定されたパラメーターに補正を追加する。
        /// </summary>
        /// <param name="id">追加対象の識別子</param>
        /// <param name="modifier">追加する補正情報</param>
        /// <returns>
        /// 追加に成功した場合はtrue。
        /// 未登録または重複補正の場合はfalse。
        /// </returns>
        public bool TryAddModifier(
            TParameter id,
            ParameterModifier modifier)
        {
            EnsureCanModify();

            if (modifier == null)
            {
                throw new ArgumentNullException(
                    nameof(modifier));
            }

            if (!TryGetParameter(id, out var parameter))
            {
                return false;
            }

            return parameter.TryAddModifier(modifier);
        }

        /// <summary>
        /// 指定されたパラメーターの補正を解除する。
        /// </summary>
        /// <param name="id">解除対象の識別子</param>
        /// <param name="modifierId">解除する補正のID</param>
        /// <returns>解除に成功した場合はtrue</returns>
        public bool TryRemoveModifier(
            TParameter id,
            Guid modifierId)
        {
            EnsureCanModify();

            if (!TryGetParameter(id, out var parameter))
            {
                return false;
            }

            return parameter.TryRemoveModifier(modifierId);
        }

        /// <summary>
        /// 指定された補正元による補正を全体から解除する。
        /// </summary>
        /// <param name="source">解除対象の補正元</param>
        /// <returns>解除した補正の合計件数</returns>
        public int RemoveModifiersBySource(object source)
        {
            EnsureCanModify();

            if (source == null)
            {
                return 0;
            }

            int removedCount = 0;

            isBulkOperating = true;

            try
            {
                // 全パラメーターから対象の補正を解除する。
                foreach (var parameter in parameters.Values)
                {
                    removedCount +=
                        parameter.RemoveModifiersBySource(source);
                }
            }
            finally
            {
                isBulkOperating = false;
            }

            return removedCount;
        }

        /// <summary>
        /// 全パラメーターの補正を解除する。
        /// </summary>
        /// <returns>解除した補正の合計件数</returns>
        public int ClearModifiers()
        {
            EnsureCanModify();

            int removedCount = 0;

            isBulkOperating = true;

            try
            {
                foreach (var parameter in parameters.Values)
                {
                    removedCount += parameter.ClearModifiers();
                }
            }
            finally
            {
                isBulkOperating = false;
            }

            return removedCount;
        }

        /// <summary>
        /// 指定されたパラメーターを初期状態に戻す。
        /// </summary>
        /// <param name="id">リセット対象の識別子</param>
        public void ResetParameter(TParameter id)
        {
            EnsureCanModify();

            GetParameter(id).Reset();
        }

        /// <summary>
        /// 全パラメーターを個体生成時の初期状態に戻す。
        /// </summary>
        /// <remarks>
        /// 基本値を初期値に戻し、すべての補正を解除する。
        /// </remarks>
        public void ResetAll()
        {
            EnsureCanModify();

            isBulkOperating = true;

            try
            {
                foreach (var parameter in parameters.Values)
                {
                    parameter.Reset();
                }
            }
            finally
            {
                isBulkOperating = false;
            }
        }

        /// <summary>
        /// 指定されたパラメーターの登録を解除する。
        /// </summary>
        /// <param name="id">解除対象の識別子</param>
        /// <returns>登録解除に成功した場合はtrue</returns>
        public bool TryUnregister(TParameter id)
        {
            EnsureCanModify();

            if (!parameters.TryGetValue(id, out var parameter))
            {
                return false;
            }

            // 登録解除前に変更イベントの購読を解除する。
            parameter.ValueChanged -= handlers[id];

            handlers.Remove(id);
            parameters.Remove(id);

            return true;
        }

        /// <summary>
        /// すべてのパラメーターの登録を解除する。
        /// </summary>
        public void Clear()
        {
            EnsureCanModify();

            ClearInternal();
        }

        /// <summary>
        /// パラメーターの変更を集合の購読者へ通知する。
        /// </summary>
        /// <param name="id">変更された識別子</param>
        /// <param name="previousValue">変更前の値</param>
        /// <param name="newValue">変更後の値</param>
        private void NotifyValueChanged(
            TParameter id,
            float previousValue,
            float newValue)
        {
            // 入れ子の通知が発生しても以前の状態を維持する。
            bool previousState = isNotifying;

            isNotifying = true;

            try
            {
                ValueChanged?.Invoke(
                    id,
                    previousValue,
                    newValue);
            }
            finally
            {
                isNotifying = previousState;
            }
        }

        /// <summary>
        /// イベント購読を解除し、登録情報を消去する。
        /// </summary>
        private void ClearInternal()
        {
            foreach (var pair in parameters)
            {
                pair.Value.ValueChanged -= handlers[pair.Key];
            }

            handlers.Clear();
            parameters.Clear();
        }

        /// <summary>
        /// 現在の状態で変更可能か検証する。
        /// </summary>
        /// <exception cref="InvalidOperationException">
        /// 変更通知中または一括操作中の場合に発生する。
        /// </exception>
        private void EnsureCanModify()
        {
            ThrowIfDisposed();

            if (isNotifying || isBulkOperating)
            {
                throw new InvalidOperationException(
                    "変更通知中または一括操作中は変更できません。");
            }
        }

        /// <summary>
        /// 破棄済みではないことを検証する。
        /// </summary>
        /// <exception cref="ObjectDisposedException">
        /// 破棄済みの場合に発生する。
        /// </exception>
        private void ThrowIfDisposed()
        {
            if (isDisposed)
            {
                throw new ObjectDisposedException(
                    GetType().Name);
            }
        }

        /// <summary>
        /// 登録情報とイベント購読を解放する。
        /// </summary>
        public void Dispose()
        {
            if (isDisposed)
            {
                return;
            }

            EnsureCanModify();

            ClearInternal();

            ValueChanged = null;

            isDisposed = true;
        }
    }
}
